// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: choices ===

// === COMMON CONTROL ===
// We want to randomize whether the relationship is a function or not.
$isFunction = rand(0, 1);

// Generate 4 ordered pairs. 
// To ensure a non-function, we must have at least one x-value repeat with a different y-value.
// To ensure a function, all x-values must be unique.

if ($isFunction) {
    // Function: Unique x-values
    $x_vals = diffrands(0, 10, 4);
    $y_vals = array();
    for ($i = 0; $i < 4; $i++) {
        $y_vals[] = rand(0, 10);
    }
    $answer = 0; // Index of "Yes"
} else {
    // Not a function: At least one x repeats with a different y
    $x_vals = array();
    $x_vals[0] = rand(0, 10);
    $x_vals[1] = $x_vals[0]; // Repeat x
    $x_vals[2] = rand(0, 10);
    // Ensure the 3rd x is different from the first to avoid accidental function
    while ($x_vals[2] == $x_vals[0]) {
        $x_vals[2] = rand(0, 10);
    }
    $x_vals[3] = rand(0, 10);
    // Ensure 4th x doesn't accidentally make it a function if we weren't careful
    // (though the repeat at index 0 and 1 already guarantees it's not a function)

    $y_vals = array();
    $y_vals[0] = rand(0, 10);
    // Ensure y is different for the repeated x
    $y_vals[1] = rand(0, 10);
    while ($y_vals[1] == $y_vals[0]) {
        $y_vals[1] = rand(0, 10);
    }
    $y_vals[2] = rand(0, 10);
    $y_vals[3] = rand(0, 10);

    $answer = 1; // Index of "No"
}

// Format the set as a string for the question text
$pairs = array();
for ($i = 0; $i < 4; $i++) {
    $pairs[] = "(" . $x_vals[$i] . ", " . $y_vals[$i] . ")";
}
$set_text = "{" . arraytolist($pairs, ", ") . "}";

$questions = array(
    "Yes, it is a function",
    "No, it is not a function"
);

// === QUESTION TEXT ===
Determine if the relationship represented by the following set of ordered pairs is a function:

`$set_text`

$answerbox

// === ANSWER ===
$solutionguide = 'A relationship is a function if every input (x-value) is paired with exactly one output (y-value). ';
if ($isFunction) {
    $solutionguide .= 'In this set, every x-value is unique, so it is a function.';
} else {
    // Find which x repeated
    $repeat_x = -1;
    for ($i = 0; $i < 4; $i++) {
        for ($j = $i + 1; $j < 4; $j++) {
            if ($x_vals[$i] == $x_vals[$j]) {
                $repeat_x = $x_vals[$i];
                break 2;
            }
        }
    }
    $solutionguide .= 'The x-value ' . $repeat_x . ' is paired with more than one different y-value, so it is not a function.';
}

// === NAME - DESCRIPTION:  ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
// Use rand() for simple ranges. 
// To get a value between 0.2 and 0.5, we use rand(0.2, 0.5).
$pA = round(rand(0.2, 0.5), 2);
$pB = round(rand(0.2, 0.5), 2);

// Ensure P(A and B) is possible: must be <= min(pA, pB)
// We pick a value between 0.01 and slightly less than the minimum of the two.
$maxAnd = min($pA, $pB) - 0.01;
if ($maxAnd < 0.01) {
    // Safety fallback to prevent rand(min, max) where min > max
    $pAnd = 0.01;
} else {
    $pAnd = round(rand(0.01, $maxAnd), 2);
}

// Final answer for P(A or B)
$pOr = $pA + $pB - $pAnd;

// Contexts for randomization
$contexts = [
    ["A" => "students who play a sport", "B" => "students who are in the band", "overlap" => "students who do both"],
    ["A" => "employees who speak Spanish", "B" => "employees who speak French", "overlap" => "employees who speak both languages"],
    ["A" => "cars that are red", "B" => "cars that are electric", "overlap" => "red electric cars"],
    ["A" => "people who drink coffee", "B" => "people who drink tea", "overlap" => "people who drink both"]
];

// randfrom(array) picks a random element from the array.
// To get an index, we use rand(0, 3).
$ctxIdx = rand(0, 3);
$ctx = $contexts[$ctxIdx];

$anstypes = "number,choices";

$answer[0] = $pOr;
$answer[1] = 0; // The correct explanation for overcounting

$questions[1] = [
    "Because the probability of the overlap is counted twice when you simply add P(A) and P(B).",
    "Because the events are mutually exclusive and cannot happen at the same time.",
    "Because the probability of the union is always the product of the individual probabilities.",
    "Because the overlap is not included in either P(A) or P(B)."
];

// Formatting for display
$pA_disp = $pA;
$pB_disp = $pB;
$pAnd_disp = $pAnd;

$solutionguide = "To find the probability of A or B, we use the Addition Rule: P(A or B) = P(A) + P(B) - P(A and B). Substituting the values: " . $pA_disp . " + " . $pB_disp . " - " . $pAnd_disp . " = " . $pOr . ". We subtract the overlap because those individuals are already included in the count for P(A) and also included in the count for P(B); adding the two probabilities without subtracting the overlap counts those individuals twice.";

