// === NAME - DESCRIPTION: Reading a Study - Classifying and Interpreting Study Designs ===
// === SET QUESTION TYPE TO: multipart ===

// === COMMON CONTROL ===
$scenarios = [
  [
    "text" => "A researcher wants to study the effect of a new vitamin supplement on memory. She recruits 100 volunteers and randomly assigns 50 to take the supplement daily and 50 to take a placebo for six months. At the end of the study, she compares the average memory test scores of the two groups.",
    "type" => "experimental",
    "bias" => "The placebo effect",
    "justified" => "The vitamin supplement caused an improvement in memory scores.",
    "not_justified" => "People who naturally have better memories are more likely to take vitamins.",
    "bias_options" => ["The placebo effect", "Sampling bias", "Non-response bias", "Confounding by diet"]
  ],
  [
    "text" => "A public health official wants to see if there is a link between coffee consumption and heart disease. He surveys 1,000 adults about their daily coffee intake and reviews their medical records for any history of heart disease over the last ten years.",
    "type" => "observational",
    "bias" => "Confounding by smoking",
    "justified" => "There is an association between coffee consumption and heart disease.",
    "not_justified" => "Drinking coffee causes an increase in the risk of heart disease.",
    "bias_options" => ["The placebo effect", "Confounding by smoking", "Random assignment error", "Double-blind failure"]
  ],
  [
    "text" => "A school district wants to know if a new tutoring program improves math scores. They identify two existing classrooms that are similar in average ability; one classroom receives the tutoring program while the other continues with the standard curriculum. At the end of the semester, the district compares the final exam averages.",
    "type" => "observational",
    "bias" => "Confounding by teacher quality",
    "justified" => "The tutored class had higher scores than the non-tutored class.",
    "not_justified" => "The tutoring program is the sole reason for the difference in scores.",
    "bias_options" => ["The placebo effect", "Confounding by teacher quality", "Non-response bias", "Volunteer bias"]
  ],
  [
    "text" => "A skincare company tests a new anti-aging cream. They recruit 60 participants and randomly assign them to two groups. Group A applies the new cream to their left cheek and a standard moisturizer to their right cheek. Group B applies the standard moisturizer to both cheeks. The company then measures wrinkle depth after eight weeks.",
    "type" => "experimental",
    "bias" => "The placebo effect",
    "justified" => "The new cream is more effective at reducing wrinkles than the standard moisturizer.",
    "not_justified" => "The participants' age was the primary driver of the results.",
    "bias_options" => ["The placebo effect", "Sampling bias", "Confounding by skin type", "Non-response bias"]
  ]
];

$idx = rand(0, 3);
$scenario = $scenarios[$idx];

$questions[0] = [
  "Observational Study",
  "Experimental Study"
];
$answer[0] = ($scenario["type"] == "experimental") ? 1 : 0;

$bias_opts = $scenario["bias_options"];
$questions[1] = $bias_opts;
$answer[1] = arrayfindindex($bias_opts, $scenario["bias"]);

$answer[2] = $scenario["justified"];
$answer[3] = $scenario["not_justified"];

$anstypes = "choices,choices,string,string";
$strflags[2] = "ignore_case,trim_whitespace";
$strflags[3] = "ignore_case,trim_whitespace";

$sol_type = ($scenario["type"] == "experimental") ? "Experimental (because treatments were randomly assigned)" : "Observational (because the researcher did not manipulate the variables)";
$sol_bias = "The most plausible issue here is " . $scenario["bias"] . ".";
$sol_just = "Since this is a " . $scenario["type"] . " study, we " . (($scenario["type"] == "experimental") ? "can" : "cannot") . " conclude causation.";

$solutionguide = "Step 1: Identify if a treatment was randomly assigned. $sol_type. \nStep 2: Identify potential lurking variables or biases. $sol_bias. \nStep 3: Determine the strength of the conclusion. $sol_just. \nJustified: " . $scenario["justified"] . " \nNot Justified: " . $scenario["not_justified"];

// === QUESTION TEXT ===
<p>Read the following study description:</p>
<p><em>"$scenario[text]"</em></p>

<p>(a) Classify this study: $answerbox[0]</p>
<p>(b) Which of the following is a plausible source of bias or confounding in this specific study? $answerbox[1]</p>
<p>(c) State one conclusion that <strong>is</strong> justified based on the design of this study: <br>$answerbox[2]</p>
<p>(d) State one conclusion that <strong>is not</strong> justified based on the design of this study: <br>$answerbox[3]</p>

