loadlibrary("stats");

// Part 1: Right-tail area logic
// We want a right-tail area of $areaRight. 
// invNorm requires the area to the LEFT.
$areaRight = randfrom([0.05, 0.025, 0.01, 0.10]);
$areaLeft = 1 - $areaRight;
$zRight = invnormalcdf($areaLeft, 0, 1);

// Part 2: Middle percentage
// We want the middle $midPct percent.
$midPct = randfrom([90, 95, 99]);
$midDec = $midPct / 100;
$tailArea = (1 - $midDec) / 2;
// The upper bound z
$zMid = invnormalcdf(1 - $tailArea, 0, 1);

$anstypes = "choices,number,number";

// Part 1 choices
$questions[0] = array(
  "The area to the left is $areaRight",
  "The area to the left is " . round($areaLeft, 3),
  "The area to the left is " . round(1 - ($areaRight/2), 3),
  "The area to the left is " . round($areaRight/2, 3)
);
$answer[0] = 1;

// Part 2: The z-score for the right tail
$answer[1] = round($zRight, 3);

// Part 3: The z-score for the middle percentage
$answer[2] = round($zMid, 3);

// Formatting for display
$areaRightDisp = round($areaRight, 3);
$midPctDisp = $midPct;

// Solution Guide
$solutionguide = "Part (a): The invNorm function calculates the z-score for a given area to the LEFT. Since we want a right-tail area of $areaRightDisp, we must use the complement: 1 - $areaRightDisp = " . round($areaLeft, 3) . ".
Part (b): Using invNorm(" . round($areaLeft, 3) . ", 0, 1), we find z = " . round($zRight, 3) . ".
Part (c): For the middle $midPctDisp%, the remaining area is " . round(1 - $midDec, 3) . ". This is split between two tails, so each tail has an area of " . round($tailArea, 3) . ". The upper critical value is the z-score where the area to the left is " . round(1 - $tailArea, 3) . ", which is z = " . round($zMid, 3) . ".";

