// Principal between 1000 and 5000, multiple of 100
$P = (rand(10, 50) * 100);

// Nominal annual interest rate between 3% and 8%, step of 0.5%
$rate_pct = randfrom(array(3, 3.5, 4, 4.5, 5, 5.5, 6, 6.5, 7, 7.5, 8));
$r = $rate_pct / 100;

// Time in years between 2 and 10
$t = rand(2, 10);

// Calculation 1: Annual Compounding
// A = P(1 + r)^t
$A_annual = $P * ((1 + $r)**$t);
$answer[0] = round($A_annual, 2);

// Calculation 2: Monthly Compounding
// A = P(1 + r/12)^(12t)
$A_monthly = $P * ((1 + $r/12)**(12 * $t));
$answer[1] = round($A_monthly, 2);

// Calculation 3: Difference
$diff = $A_monthly - $A_annual;
$answer[2] = round($diff, 2);

$anstypes = "number,number,number";

// Formatting for display - using makeprettydisp instead of number_format
$P_disp = makeprettydisp($P);
$rate_disp = $rate_pct;

// Solution Guide
$sol_annual = "A = " . $P . " * (1 + " . $r . ")^" . $t . " = " . round($A_annual, 4);
$sol_monthly = "A = " . $P . " * (1 + " . round($r/12, 6) . ")^" . (12 * $t) . " = " . round($A_monthly, 4);
$sol_diff = round($diff, 2);

$solutionguide = "Part (a): Using the annual compounding formula `A = P(1 + r)^t`, we have `A = " . $P . "(1 + " . $r . ")^" . $t . " = " . $sol_annual . "`. Rounded to two decimal places, this is $" . $answer[0] . ". \n\nPart (b): Using the monthly compounding formula `A = P(1 + r/n)^(nt)` where `n = 12`, we have `A = " . $P . "(1 + " . round($r/12, 6) . ")^" . (12 * $t) . " = " . $sol_monthly . "`. Rounded to two decimal places, this is $" . $answer[1] . ". \n\nPart (c): The difference is $" . $answer[1] . " - $" . $answer[0] . " = $" . $sol_diff . ".";

