// Randomize the profit per candle type
// Candle A: $10 to $20, Candle B: $15 to $25
$profitA = rand(10, 20);
$profitB = rand(15, 25);

// Randomize resource constraints (Wax and Scent)
// Wax: 100 to 200 units available
// Scent: 60 to 120 units available
$waxAvail = rand(100, 200);
$scentAvail = rand(60, 120);

// Resource usage per candle
// Candle A: 2-4 wax, 1-2 scent
// Candle B: 3-5 wax, 2-3 scent
$waxA = rand(2, 4);
$waxB = rand(3, 5);
$scentA = rand(1, 2);
$scentB = rand(2, 3);

// Ensure the constraints are not identical
while ($waxA == $waxB && $scentA == $scentB) {
    $waxB = rand(3, 5);
}

// Objective function: P = $profitA*x + $profitB*y
// Constraints:
// $waxA*x + $waxB*y <= $waxAvail
// $scentA*x + $scentB*y <= $scentAvail
// x, y >= 0

// Solve the system for the vertices of the feasible region
// Vertex 1: (0, 0)
// Vertex 2: (0, min($waxAvail/$waxB, $scentAvail/$scentB))
// Vertex 3: (min($waxAvail/$waxA, $scentAvail/$scentA), 0)
// Vertex 4: Intersection of $waxA*x + $waxB*y = $waxAvail and $scentA*x + $scentB*y = $scentAvail
// Using Cramer's Rule:
$det = ($waxA * $scentB) - ($waxB * $scentA);

// Ensure the lines are not parallel and intersect in the first quadrant
// If det is 0 or intersection is negative, re-roll
if ($det == 0) {
    // This is a rare case given the ranges, but we handle it by forcing a re-roll via a loop in a real scenario.
    // For this script, we'll adjust values to ensure a valid intersection.
    $waxA = 2; $waxB = 5; $scentA = 2; $scentB = 3;
    $det = ($waxA * $scentB) - ($waxB * $scentA);
}

$xInt = (($waxAvail * $scentB) - ($waxB * $scentAvail)) / $det;
$yInt = (($waxA * $scentAvail) - ($waxAvail * $scentA)) / $det;

// If intersection is outside first quadrant, adjust constraints to ensure a meaningful problem
if ($xInt < 0 || $yInt < 0) {
    // Simple fix: make the available resources large enough
    $waxAvail = 500;
    $scentAvail = 500;
    $xInt = (($waxAvail * $scentB) - ($waxB * $scentAvail)) / $det;
    $yInt = (($waxA * $scentAvail) - ($waxAvail * $scentA)) / $det;
}

// Calculate profits at vertices
$p0 = 0;
$pX = $profitA * min($waxAvail / $waxA, $scentAvail / $scentA);
$pY = $profitB * min($waxAvail / $waxB, $scentAvail / $scentB);
$pInt = ($profitA * $xInt) + ($profitB * $yInt);

$maxProfit = max($pX, $pY, $pInt);
$bestX = ($maxProfit == $pInt) ? $xInt : (($maxProfit == $pX) ? min($waxAvail / $waxA, $scentAvail / $scentA) : 0);
$bestY = ($maxProfit == $pInt) ? $yInt : (($maxProfit == $pY) ? min($waxAvail / $waxB, $scentAvail / $scentB) : 0);

$anstypes = "number,number,number";
$answer[0] = round($bestX, 2);
$answer[1] = round($bestY, 2);
$answer[2] = round($maxProfit, 2);

$solutionguide = "Step 1: Define variables. Let x be the number of Candle A and y be the number of Candle B.
Step 2: Set up the objective function: P = $profitA*x + $profitB*y.
Step 3: Set up constraints:
Wax: $waxA*x + $waxB*y <= $waxAvail
Scent: $scentA*x + $scentB*y <= $scentAvail
Non-negativity: x >= 0, y >= 0.
Step 4: Use the simplex method or vertex testing. The vertices are (0,0), ($waxAvail/$waxA, 0) or ($scentAvail/$scentA, 0), (0, $waxAvail/$waxB) or (0, $scentAvail/$scentB), and the intersection of the two constraint lines.
Step 5: The intersection is found by solving the system of equations.
Step 6: Compare the profit at each vertex to find the maximum.";

