// We need a 3x3 matrix A that is invertible and has an integer inverse to keep it student-friendly,
// or at least a matrix where the inverse and the solution X are "clean".
// A reliable way to generate an invertible matrix with an integer inverse is to multiply 
// three elementary matrices or start with an integer inverse and invert it.
// Alternatively, we can pick a matrix with a small non-zero determinant.

// To ensure the inverse is "nice" (integers), we can generate a matrix with det = 1 or -1.
// Let's use a known method: A = L * U where L is lower triangular with 1s on diagonal 
// and U is upper triangular with 1s on diagonal. Then det(A) = 1.

$l11 = 1;
$l21 = rand(-2, 2);
$l22 = 1;
$l31 = rand(-2, 2);
$l32 = rand(-2, 2);
$l33 = 1;

$u11 = 1;
$u12 = rand(-2, 2);
$u13 = rand(-2, 2);
$u22 = 1;
$u23 = rand(-2, 2);
$u33 = 1;

// A = L * U
$a11 = $l11 * $u11;
$a12 = $l11 * $u12;
$a13 = $l11 * $u13;

$a21 = $l21 * $u11;
$a22 = $l21 * $u12 + $l22 * $u22;
$a23 = $l21 * $u13 + $l22 * $u23;

$a31 = $l31 * $u11;
$a32 = $l31 * $u12 + $l32 * $u22;
$a33 = $l31 * $u13 + $l32 * $u23 + $l33 * $u33;

// Calculate A inverse. Since det(A)=1, A^-1 = adj(A).
// Cofactors C_ij
$c11 = $a22 * $a33 - $a23 * $a32;
$c12 = -($a21 * $a33 - $a23 * $a31);
$c13 = $a21 * $a32 - $a22 * $a31;

$c21 = -($a12 * $a33 - $a13 * $a32);
$c22 = $a11 * $a33 - $a13 * $a31;
$c23 = -($a11 * $a32 - $a12 * $a31);

$c31 = $a12 * $a23 - $a13 * $a22;
$c32 = -($a11 * $a23 - $a13 * $a21);
$c33 = $a11 * $a22 - $a12 * $a21;

// A_inv is the transpose of the cofactor matrix
$inv11 = $c11; $inv12 = $c21; $inv13 = $c31;
$inv21 = $c12; $inv22 = $c22; $inv23 = $c32;
$inv31 = $c13; $inv32 = $c23; $inv33 = $c33;

$answer[0] = "[[$inv11,$inv12,$inv13],[$inv21,$inv22,$inv23],[$inv31,$inv32,$inv33]]";

// Generate B such that X = A^-1 * B is an integer vector.
// Pick X first, then B = A * X.
$x1 = rand(-5, 5);
$x2 = rand(-5, 5);
$x3 = rand(-5, 5);

$b1 = $a11 * $x1 + $a12 * $x2 + $a13 * $x3;
$b2 = $a21 * $x1 + $a22 * $x2 + $a23 * $x3;
$b3 = $a31 * $x1 + $a32 * $x2 + $a33 * $x3;

$answer[1] = "[[$x1],[$x2],[$x3]]";

$anstypes = "calcmatrix,calcmatrix";

// Formatting for display
$matA = "[[$a11,$a12,$a13],[$a21,$a22,$a23],[$a31,$a32,$a33]]";
$matB = "[[$b1],[$b2],[$b3]]";

