// Context: Height of a projectile or a falling object.
// h(t) = -4.9t^2 + v0*t + h0
$v0 = rand(10, 25); // Initial velocity
$h0 = rand(1, 10);  // Initial height
$v0 = round($v0, 1);
$h0 = round($h0, 1);

// Part 1: Evaluate at a specific time
$t_eval = rand(1, 3);
$h_eval = -4.9 * ($t_eval**2) + $v0 * $t_eval + $h0;
$answer[0] = round($h_eval, 2);

// Part 2: Domain
// The function is physically meaningful from t=0 until it hits the ground (h=0).
// 0 = -4.9t^2 + v0*t + h0
// t = (-v0 - sqrt(v0^2 - 4(-4.9)(h0))) / (2 * -4.9)
$discriminant = ($v0**2) - (4 * -4.9 * $h0);
$t_end = (-$v0 - sqrt($discriminant)) / (2 * -4.9);
$t_end_rounded = round($t_end, 2);
$answer[1] = "[0, $t_end_rounded]";

// Part 3: Average Rate of Change (AROC)
// Interval [t1, t2]
$t1 = 1;
$t2 = $t_eval; 
if ($t2 == $t1) { $t2 = 2; } // Ensure interval is not zero

$h1 = -4.9 * ($t1**2) + $v0 * $t1 + $h0;
$h2 = -4.9 * ($t2**2) + $v0 * $t2 + $h0;
$aroc = ($h2 - $h1) / ($t2 - $t1);
$answer[2] = round($aroc, 2);

$anstypes = "number,interval,number";

// Solution Guide
$solutionguide = "Part (a): Substitute `t = $t_eval` into the function: `h($t_eval) = -4.9($t_eval)^2 + $v0($t_eval) + $h0 = $answer[0]`.
Part (b): The domain starts at `t = 0`. The object hits the ground when `h(t) = 0`. Using the quadratic formula, `t = $t_end_rounded`. Thus, the domain is `[0, $t_end_rounded]`.
Part (c): The average rate of change over `[$t1, $t2]` is `(h($t2) - h($t1)) / ($t2 - $t1)`. 
`h($t1) = ` . round($h1, 2) . ` and `h($t2) = ` . round($h2, 2) . `.
AROC = ` . round($h2 - $h1, 2) . ` / " . ($t2 - $t1) . " = $answer[2].";

