// Randomize slope m = n1/d1
$n1 = rand(-5, 5);
if ($n1 == 0) { $n1 = 1; }
$d1 = rand(2, 6);
// Ensure m is simplified
$gcd1 = gcd(abs($n1), $d1);
$m_num = $n1 / $gcd1;
$m_den = $d1 / $gcd1;

// Randomize intercept b = n2/d2
$n2 = rand(-5, 5);
$d2 = rand(2, 6);
// Ensure b is simplified
$gcd2 = gcd(abs($n2), $d2);
$b_num = $n2 / $gcd2;
$b_den = $d2 / $gcd2;

// Generate 3 x-values. Let's use small integers to keep y-values manageable.
$x_vals = array(0, 1, 2);
// To make it more interesting, we can shift the x-values
$x_shift = rand(-2, 2);
for ($i = 0; $i < 3; $i++) {
    $x_vals[$i] += $x_shift;
}

// Calculate y-values as fractions
// y = (m_num/m_den)*x + (b_num/b_den)
// y = (m_num * x * b_den + b_num * m_den) / (m_den * b_den)
$y_vals_str = array();
for ($i = 0; $i < 3; $i++) {
    $x = $x_vals[$i];
    $num = ($m_num * $x * $b_den) + ($b_num * $m_den);
    $den = $m_den * $b_den;

    $common = gcd(abs($num), $den);
    $final_num = $num / $common;
    $final_den = $den / $common;

    if ($final_den == 1) {
        $y_vals_str[$i] = $final_num;
    } else {
        $y_vals_str[$i] = $final_num . "/" . $final_den;
    }
}

// The answer is the function y = mx + b
$answer = "($m_num/$m_den)*x + ($b_num/$b_den)";

// For the solution guide, we need the decimal or simplified fraction forms
